import safetyPageData from '../data/pages/safetyPageData.js';
import usePageMeta from '../functions/usePageMeta.js';
import useToTop from '../functions/useToTop.js';
import LazyYoutube from '../components/LazyYoutube.js';

const SafetyPage = () => {
  useToTop();
  usePageMeta({
    title: 'Drošība',
    description:
      'Mums ir svarīga jūsu drošība uguņošanas laikā. Tropiks AZ ieteikumi drošai pirotehnikas lietošanai.',
    path: '/drosiba',
  });

  const data = safetyPageData[0];

  return (
    <main className="safety-page">
      <section className="main-page-title">
        <h1>
          Šaujiet <span>DROŠI!</span>
        </h1>
        <div className="page-lead safety-intro">
          {data.subText.map((e) => (
            <p key={e.id}>{e.text}</p>
          ))}
        </div>
      </section>

      <section className="safety-video-block">
        <LazyYoutube
          embedUrl={data.safetyVideo}
          title="YouTube video, kurā ir izskaidroti pirotehnikas lietošanas noteikumi"
        />
      </section>

      <section className="safety-rules">
        <h2>{data.rulesIntro}</h2>
        <ol className="safety-rules-grid">
          {data.otherRules.map((e, index) => (
            <li key={e.id} className="safety-rule-card">
              <span className="safety-rule-number" aria-hidden="true">
                {String(index + 1).padStart(2, '0')}
              </span>
              <p>{e.text}</p>
            </li>
          ))}
        </ol>
      </section>
    </main>
  );
};

export default SafetyPage;
